-- Option A: Drop the column and compute on read (recommended if no raw SQL reports):
ALTER TABLE invoice_items DROP COLUMN line_total;
-- Then all SELECTs use: (quantity * unit_price) AS line_total

-- Option B: Replace with a generated column (MySQL 5.7.6+):
ALTER TABLE invoice_items DROP COLUMN line_total;
ALTER TABLE invoice_items ADD COLUMN line_total DECIMAL(12,2) GENERATED ALWAYS AS (quantity * unit_price) STORED;

-- Add a staleness indicator:
ALTER TABLE gst_compliance_periods
  ADD COLUMN snapshot_at DATETIME NULL COMMENT 'When this snapshot was computed',
  ADD COLUMN is_stale TINYINT(1) NOT NULL DEFAULT 0 COMMENT 'Set to 1 when any source invoice/payment changes after snapshot_at';
-- Add triggers to mark stale when invoices or payments change:
DROP TRIGGER IF EXISTS trg_invoice_stale_gst;
CREATER TRIGGER trg_invoice_stale_gst AFTER UPDATE ON invoices
FOR EACH ROW BEGIN
  UPDATE gst_compliance_periods
     SET is_stale = 1
   WHERE period_key = DATE_FORMAT(NEW.created_at, '%Y-%m')
     AND status IN ('draft', 'reviewed');
END;

-- Add a DB trigger as a safety net for available_quantity:
DROP TRIGGER IF EXISTS trg_sync_available_qty;
CREATE TRIGGER trg_sync_available_qty BEFORE UPDATE ON inventory_stock
FOR EACH ROW BEGIN
  SET NEW.available_quantity = NEW.current_quantity - NEW.reserved_quantity;
  SET NEW.is_low_stock = IF(
    NEW.available_quantity <= (SELECT reorder_level FROM inventory_products WHERE inv_product_id = NEW.inv_product_id),
    1, 0
  );
END;

ALTER TABLE inventory_reorder_suggestions
  CHANGE COLUMN current_stock  current_stock_snapshot  DECIMAL(14,3) NOT NULL DEFAULT 0.000 COMMENT 'inventory_stock.available_quantity at suggestion time',
  CHANGE COLUMN reorder_level  reorder_level_snapshot  DECIMAL(14,3) NOT NULL DEFAULT 0.000 COMMENT 'inventory_products.reorder_level at suggestion time';
